contract_input={'syntheticOnly':True,'contract':fixture['contract'],'expectedContract':fixture['contract'],'ledgerRows':fixture['rows'],'mappings':fixture['mappings'],'bindings':[]}
for m in fixture['mappings']:
    brand=m['BRANDCD'];item=items[brand]
    binding={'displayBrand':brand,'displayStyle':styles[brand],'BRANDCD':brand,'STYLECD':m['STYLECD'],'erpScope':fixture['erpScope'],'marketScope':fixture['marketScope'],'categoryCrosswalk':{**fixture['categoryCrosswalk'],'item':item}}
    contract_input['bindings'].append(binding)
screen_request={k:fixture['contract'][k] for k in ['period','brands','season','grain','channelScope']}
screen_request['sourceContract']=fixture['contract']
screen_request['bindings']=[{'displayBrand':b['displayBrand'],'displayStyle':b['displayStyle'],'BRANDCD':b['BRANDCD'],'STYLECD':b['STYLECD'],'item':items[b['displayBrand']],'category':fixture['categoryCrosswalk']['category'],'store':fixture['marketScope']['store'],'gender':fixture['marketScope']['gender'],'age':fixture['marketScope']['age']} for b in contract_input['bindings']]
